import{_ as s,o as a,c as t,a3 as i}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"Start and stop","description":"","frontmatter":{},"headers":[],"relativePath":"run/start-stop.md","filePath":"run/start-stop.md"}'),o={name:"run/start-stop.md"};function n(r,e,p,d,l,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="start-and-stop" tabindex="-1">Start and stop <a class="header-anchor" href="#start-and-stop" aria-label="Permalink to &quot;Start and stop&quot;">​</a></h1><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><p>Wake runs in Docker, and its services restart with Docker. When Docker is not running, after a reboot or after Docker Desktop was quit, Wake is down too.</p><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><p><code>wake-server start</code> brings Wake back:</p><ul><li>On macOS it opens Docker Desktop when Docker is not running and waits up to 120 seconds for it (<code>WAKE_DOCKER_TIMEOUT</code> changes the wait).</li><li>On Linux, start the Docker service first, for example <code>sudo systemctl start docker</code>.</li></ul><p>It then starts Wake as it is installed, pulling and changing nothing, waits until it is healthy and prints <code>Wake &lt;version&gt; is running at &lt;address&gt;</code>. Running it while Wake already runs changes nothing. It also applies changes you made to <code>.env</code>, such as <a href="/wake-dist/docs/run/sign-in-providers">sign-in providers</a>, by recreating the services that use them.</p><p><code>start</code> and <code>stop</code> do not run while an upgrade, a backup or a restore does: they exit <code>1</code> saying <code>an upgrade, backup or restore is running</code>. Run them again when it finishes.</p><h2 id="come-back-after-a-reboot" tabindex="-1">Come back after a reboot <a class="header-anchor" href="#come-back-after-a-reboot" aria-label="Permalink to &quot;Come back after a reboot&quot;">​</a></h2><p>Wake comes back by itself whenever Docker starts, unless you stopped it with <code>wake-server stop</code>. To have Docker start with the machine:</p><ul><li>On Linux, enable the Docker service once: <code>sudo systemctl enable docker</code>.</li><li>On macOS, turn on Docker Desktop&#39;s <strong>Settings → General → Start Docker Desktop when you sign in</strong>.</li></ul><h2 id="stop" tabindex="-1">Stop <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;Stop&quot;">​</a></h2><p><code>wake-server stop</code> stops Wake and keeps its containers, volumes, backups and settings. Wake stays stopped, also across Docker restarts and reboots, until <code>wake-server start</code>.</p><p><code>wake-server upgrade</code>, <code>backup</code> and <code>restore</code> need Docker running and say so when it is not.</p><h2 id="remove-wake" tabindex="-1">Remove Wake <a class="header-anchor" href="#remove-wake" aria-label="Permalink to &quot;Remove Wake&quot;">​</a></h2><p>Removing Wake deletes its data: every project, task, account and evidence file. Keep a backup somewhere else if you may want them back.</p><ol><li><p>Back up, with Wake running, and copy the file off the machine, because step 4 deletes <code>backups/</code> too:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span></code></pre></div></li><li><p>Turn off the daily upgrades, which removes Wake&#39;s line from your crontab:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto-upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span></code></pre></div></li><li><p>Stop Wake and delete its containers and data, from your installation directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> installation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>Add <code>--rmi all</code> to delete Wake&#39;s images too.</p></li><li><p>Delete the files Wake installed:</p><ul><li>your installation directory, with its settings and backups;</li><li><code>wake-server</code> on your <code>PATH</code>, <code>~/.local/bin/wake-server</code> unless you set <code>WAKE_BIN_DIR</code>;</li><li>the CLI&#39;s settings, <code>~/.config/wake/</code> (or <code>$XDG_CONFIG_HOME/wake/</code>).</li></ul></li><li><p>In each repository you connected, remove what <code>wake connect</code> added, once per agent:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disconnect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p>The agents are <code>claude-code</code>, <code>opencode</code>, <code>pi</code> and <code>codex</code>. Delete <code>.wake/</code> from the repository if you no longer want its Wake settings.</p></li><li><p>Remove the CLI, on every machine that has it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @wake/cli</span></span></code></pre></div><p>Its token stays in your system&#39;s keychain under the service <code>wake</code>; delete it there, for example in Keychain Access on macOS.</p></li></ol>`,17)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
